                // 59: PITCH_SET
                1856: initial_byte=8'd134;
                1857: initial_byte=8'd6;
                1858: initial_byte=8'd80;
                1859: initial_byte=8'd73;
                1860: initial_byte=8'd84;
                1861: initial_byte=8'd67;
                1862: initial_byte=8'd72;
                1863: initial_byte=8'd44;
                // 60: VIB_SET
                1888: initial_byte=8'd132;
                1889: initial_byte=8'd4;
                1890: initial_byte=8'd86;
                1891: initial_byte=8'd73;
                1892: initial_byte=8'd66;
                1893: initial_byte=8'd44;
                // 62: EFFECT2_SET
                1920: initial_byte=8'd136;
                1921: initial_byte=8'd8;
                1922: initial_byte=8'd69;
                1923: initial_byte=8'd70;
                1924: initial_byte=8'd70;
                1925: initial_byte=8'd69;
                1926: initial_byte=8'd67;
                1927: initial_byte=8'd84;
                1928: initial_byte=8'd50;
                1929: initial_byte=8'd44;
                default:initial_byte=0;
            endcase
        end
    endfunction
    genvar address;
    generate for(address=0;address<ROM_BYTES;address=address+1)begin: init_rom
        initial dictionary[address]=initial_byte(address);
    end endgenerate
    reg [10:0] rom_address;
    reg [7:0] rom_q;
    always @(posedge clk)rom_q<=dictionary[rom_address];
    reg [2:0] state;
    reg [5:0] template_index;
    wire [5:0] next_template=template_index+6'd1;
    wire [5:0] matched_command=template_index==6'd60 ? 6'd62 : template_index+6'd1;
    reg [4:0] pattern_length;
    reg [6:0] saved_length;
    task advance;
        begin
            if(template_index==COMMAND_COUNT-1)begin
                command<=0;done<=1;state<=IDLE;
            end else begin
                template_index<=next_template;
                rom_address<={next_template,5'd0};state<=HEADER_WAIT;
            end
        end
    endtask
    always @(posedge clk)begin
        if(!resetn)begin
            state<=IDLE;template_index<=0;rom_address<=0;position<=0;
            saved_length<=0;pattern_length<=0;command<=0;done<=0;
        end else begin
            done<=0;
            case(state)
                IDLE:if(start)begin
                    saved_length<=line_length;template_index<=0;rom_address<=0;
                    command<=0;position<=0;state<=HEADER_WAIT;
                end
                HEADER_WAIT:state<=HEADER;
                HEADER:if(rom_q[7] ? saved_length>rom_q[6:0] : saved_length==rom_q[6:0])begin
                    rom_address<=rom_address+11'd1;state<=LENGTH_WAIT;
                end else advance;
                LENGTH_WAIT:state<=LENGTH;
                LENGTH:begin
                    pattern_length<=rom_q[4:0];position<=0;
                    rom_address<=rom_address+11'd1;state<=CHAR_WAIT;
                end
                CHAR_WAIT:state<=CHARACTER;
                CHARACTER:if(character!=rom_q)advance;
                    else if(position=={1'b0,pattern_length}-6'd1)begin
                        command<=matched_command;done<=1;state<=IDLE;
                    end else begin
                        position<=position+6'd1;rom_address<=rom_address+11'd1;
                        state<=CHAR_WAIT;
                    end
                default:state<=IDLE;
            endcase
        end
    end
endmodule
